import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>
__global__ void min_reduce_kernel(const float* __restrict__ x,
                                   float* __restrict__ out,
                                   long outer_size,
                                   long reduce_size,
                                   long inner_size) {
    long total = outer_size * inner_size;
    long stride = (long)blockDim.x * gridDim.x;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += stride) {
        long outer_idx = idx / inner_size;
        long inner_idx = idx % inner_size;
        const float* base = x + outer_idx * reduce_size * inner_size + inner_idx;
        float min0 = __ldg(base);
        float min1 = FLT_MAX;
        float min2 = FLT_MAX;
        float min3 = FLT_MAX;
        long r = 1;
        #pragma unroll 4
        for (; r + 3 < reduce_size; r += 4) {
            float v0 = __ldg(base + r * inner_size);
            float v1 = __ldg(base + (r + 1) * inner_size);
            float v2 = __ldg(base + (r + 2) * inner_size);
            float v3 = __ldg(base + (r + 3) * inner_size);
            min0 = fminf(min0, v0);
            min1 = fminf(min1, v1);
            min2 = fminf(min2, v2);
            min3 = fminf(min3, v3);
        }
        for (; r < reduce_size; r++) {
            float v = __ldg(base + r * inner_size);
            min0 = fminf(min0, v);
        }
        float min_val = fminf(fminf(min0, min1), fminf(min2, min3));
        out[idx] = min_val;
    }
}
__global__ void min_reduce_kernel_vec4(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        long outer_size,
                                        long reduce_size,
                                        long inner_size,
                                        long inner_vec) {
    long total = outer_size * inner_vec;
    long stride = (long)blockDim.x * gridDim.x;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += stride) {
        long outer_idx = idx / inner_vec;
        long vec_idx = idx % inner_vec;
        long col0 = vec_idx * 4;
        const float* base = x + outer_idx * reduce_size * inner_size + col0;
        float4 min_val = *reinterpret_cast<const float4*>(base);
        for (long r = 1; r < reduce_size; r++) {
            float4 v = *reinterpret_cast<const float4*>(base + r * inner_size);
            min_val.x = fminf(min_val.x, v.x);
            min_val.y = fminf(min_val.y, v.y);
            min_val.z = fminf(min_val.z, v.z);
            min_val.w = fminf(min_val.w, v.w);
        }
        float* out_base = out + outer_idx * inner_size + col0;
        *reinterpret_cast<float4*>(out_base) = min_val;
    }
}
__global__ void min_reduce_kernel_tail(const float* __restrict__ x,
                                        float* __restrict__ out,
                                        long outer_size,
                                        long reduce_size,
                                        long inner_size,
                                        long inner_vec,
                                        long remainder) {
    long total = outer_size * remainder;
    long stride = (long)blockDim.x * gridDim.x;
    for (long idx = blockIdx.x * (long)blockDim.x + threadIdx.x; idx < total; idx += stride) {
        long outer_idx = idx / remainder;
        long rem_idx = idx % remainder;
        long inner_idx = inner_vec * 4 + rem_idx;
        const float* base = x + outer_idx * reduce_size * inner_size + inner_idx;
        float min_val = __ldg(base);
        #pragma unroll 4
        for (long r = 1; r < reduce_size; r++) {
            float v = __ldg(base + r * inner_size);
            min_val = fminf(min_val, v);
        }
        out[outer_idx * inner_size + inner_idx] = min_val;
